import json
import os

# Check ALL meeting transcripts across ALL products for any "competitor product" or specific competitor names
products_dir = 'DATA/products'
for f in os.listdir(products_dir):
    if f.endswith('.json'):
        with open(os.path.join(products_dir, f)) as fp:
            data = json.load(fp)
        for m in data.get('meeting_transcripts', []):
            text = m.get('transcript', '').lower()
            if 'competitor product' in text or 'a competitor' in text:
                print(f"  File: {f}, Meeting: {m.get('id')}")
                # Find the relevant lines
                for line in m.get('transcript', '').split('\n'):
                    if 'competitor' in line.lower():
                        print(f"    {line[:300]}")
                print()
